501	func resolveTrailReviewTarget(ctx context.Context, client *api.Client, selector, repoOverride, branchOverride string) (trailReviewTarget, error) {
502		host, owner, repo, err := resolveTrailRepoOrRemote(ctx, repoOverride)
503		if err != nil {
504			return trailReviewTarget{}, err
505		}
506	
507		selector = strings.TrimSpace(selector)
508		var found *api.TrailResource
509		if selector != "" {
510			found, err = findTrailBySelector(ctx, client, host, owner, repo, selector)
511			if err != nil {
512				return trailReviewTarget{}, err
513			}
514			if found == nil {
515				return trailReviewTarget{}, fmt.Errorf("no trail %q found in %s/%s/%s (run 'entire trail list --status any')", selector, host, owner, repo)
516			}
517		} else {
518			branch, branchErr := resolveTrailBranch(ctx, branchOverride)
519			if branchErr != nil {
520				return trailReviewTarget{}, fmt.Errorf("%w: no trail selector given and current branch is unknown: %w\nhint: run 'entire trail list --status any' or pass --trail <number|id|branch>", errTrailReviewDefaultTargetNotFound, branchErr)
521			}
522			found, err = findTrailByBranch(ctx, client, host, owner, repo, branch)
523			if err != nil {
524				return trailReviewTarget{}, err
525			}
526			if found == nil {
527				return trailReviewTarget{}, fmt.Errorf("%w: no trail found for branch %q\nhint: run 'entire trail create', 'entire trail list --status any', or pass --trail <number|id|branch>", errTrailReviewDefaultTargetNotFound, branch)
528			}
529		}
530		if found.ID == "" {
531			return trailReviewTarget{}, errors.New("trail has no id yet")
532		}
533		if found.Number <= 0 {
534			return trailReviewTarget{}, errors.New("trail has no number yet")
535		}
536		// Review helpers carry the stable trail ID internally, but entire-api's
537		// public routes are repo/number addressed. Register that translation once
538		// when the target is resolved so findings, snapshots, and SSE all hit the
539		// owning cell's native route.
540		client.SetTrailRoute(found.ID, trailNumberPath(host, owner, repo, found.Number))
541		return trailReviewTarget{Host: host, Owner: owner, Repo: repo, Trail: *found}, nil
